WITH parsed AS (SELECT id, plan, effective_from, currency, tier_limits, tier_prices, ZIP_WITH(tier_prices, discounts, (p, d) -> ROUND(p * (1 - d), 2)) AS net_prices, ELEMENT_AT(tier_prices, 1) AS entry_price, TRANSFORM(tier_prices, (p, i) -> ROUND(p * tier_limits[i], 2)) AS tier_revenue_caps FROM price_tiers) SELECT CASE WHEN entry_price >= 32 THEN 'PREMIUM' ELSE 'STANDARD' END AS entry_price_tier, MAX(entry_price) FILTER (WHERE currency = 'THB') AS thb_max_entry_price, SUM(entry_price) AS total_entry_price, APPROX_PERCENTILE(entry_price, 0.95) AS entry_price_p95, SUM(CASE WHEN plan = 'basic' THEN entry_price ELSE 0 END) AS basic_entry_price, MAX(entry_price) FILTER (WHERE currency = 'USD') AS usd_max_entry_price FROM parsed GROUP BY CUBE (CASE WHEN entry_price >= 32 THEN 'PREMIUM' ELSE 'STANDARD' END);
